 data:=jsonb_build_object('id_kavling',lot,'nama_konsumen',prefix,'status_sales','BOOKING','jenis_pembayaran','CASH_BERTAHAP','tgl_booking',today,'tenor_bulan',6,'pola_pelunasan','CICILAN_FLEKSIBEL');
